input.sparql:
SELECT ?zone ?label WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?label .
  FILTER (CONTAINS(lcase(?label), "basement") || CONTAINS(?label, "ZN_3"))
}

SELECT ?zone ?label WHERE {
  ?zone rdfs:label ?label .
  FILTER (CONTAINS(lcase(str(?zone)), "basement") || CONTAINS(str(?zone), "ZN_3"))
} LIMIT 50

SELECT ?s ?label WHERE {
  ?s rdfs:label ?label .
  FILTER (CONTAINS(?label, "ZN_3") || CONTAINS(?label, "basement") || CONTAINS(?label, "Basement"))
} LIMIT 100

SELECT ?point ?tsid WHERE {
  ?zone rdfs:label ?label .
  FILTER (?label IN ("Basement","Perimeter_top_ZN_3"))
  {
    ?point brick:isPointOf ?zone
  } UNION {
    ?zone brick:hasPoint ?point
  }
  ?point ?p ?q .
  FILTER (CONTAINS(str(?q), "Occupancy") || CONTAINS(str(?point), "Occupancy"))
  OPTIONAL { ?point ref:hasExternalReference ?tsref . ?tsref ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid2 }
}

SELECT ?point WHERE {
  ?zone rdfs:label ?label .
  FILTER (?label IN ("Basement","Perimeter_top_ZN_3"))
  ?point brick:isPointOf ?zone
}

